// Helper SweetAlert2 — înlocuiesc confirm/alert native
function mgConfirm(opts) {
  // opts: { title, html, confirmText, cancelText, icon, confirmColor }
  return Swal.fire({
    title: opts.title || 'Confirmare',
    html: opts.html || '',
    icon: opts.icon || 'question',
    showCancelButton: true,
    confirmButtonText: opts.confirmText || 'Da, continuă',
    cancelButtonText: opts.cancelText || 'Anulează',
    confirmButtonColor: opts.confirmColor || 'var(--am,#4CTS3FF)',
    background: 'var(--bg2,#0e131c)',
    color: 'var(--tx,#e6edf3)',
    customClass: { popup: 'mg-swal-popup' },
  }).then(function(r) { return r.isConfirmed; });
}
function mgToast(icon, title, timer) {
  Swal.fire({
    toast: true, position: 'top-end', showConfirmButton: false,
    timer: timer || 3000, timerProgressBar: true,
    icon: icon, title: title,
    background: 'var(--bg2,#0e131c)',
    color: 'var(--tx,#e6edf3)',
  });
}

// Copiaza text in clipboard cu fallback pentru context non-securizat (http://),
// unde navigator.clipboard nu exista. Arata toast la succes, fara prompt.
function mgCopy(text, okMsg) {
  function ok() { mgToast('success', okMsg || 'Copiat în clipboard', 1400); }
  function fallback() {
    try {
      var ta = document.createElement('textarea');
      ta.value = text;
      ta.style.position = 'fixed'; ta.style.top = '-1000px'; ta.style.opacity = '0';
      document.body.appendChild(ta); ta.focus(); ta.select();
      var done = document.execCommand('copy');
      document.body.removeChild(ta);
      if (done) { ok(); } else { mgToast('error', 'Nu s-a putut copia', 1800); }
    } catch (e) { mgToast('error', 'Nu s-a putut copia', 1800); }
  }
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(ok).catch(fallback);
  } else { fallback(); }
}

