function Icon({ id, size }) {
  return h('svg', {
    xmlns: 'http://www.w3.org/2000/svg', width: size||16, height: size||16,
    viewBox: '0 0 24 24', fill: 'none', stroke: 'currentColor',
    strokeWidth: '2', strokeLinecap: 'round', strokeLinejoin: 'round',
    style: { flexShrink:0, display:'block' },
    dangerouslySetInnerHTML: { __html: ICONS[id] || '' }
  });
}

function getToken() { return sessionStorage.getItem('mg_token'); }
function setToken(t) { sessionStorage.setItem('mg_token', t); }
function clearToken() { sessionStorage.removeItem('mg_token'); }

// Parseaza raspunsul: daca NU e JSON (ex. pagina 504 HTML de la nginx cand procesarea AI
// dureaza prea mult) arunca o eroare CLARA in loc de „Unexpected token '<'".
async function _parseResp(r) {
  if (r.status === 401) { clearToken(); location.reload(); return; }
  if (r.status === 204 || r.status === 205) return null;
  const ct = (r.headers.get('content-type') || '');
  if (ct.indexOf('application/json') !== -1) return r.json();
  let txt = '';
  try { txt = await r.text(); } catch (e) {}
  if (r.ok) return null;
  if (r.status === 504 || r.status === 502 || r.status === 503 || /gateway time-?out|<html/i.test(txt))
    throw new Error('Serverul AI a depășit timpul de procesare (' + r.status + '). Operația durează prea mult — reîncearcă în câteva momente.');
  throw new Error('Răspuns invalid de la server (HTTP ' + r.status + ').');
}

// fetch cu AbortController: nu lasa un request sa atarne minute intregi (re-click-urile
// pe actiunile AI ar ingramadi load). timeoutMs implicit 75s (peste fail-fast-ul backend ~40s).
async function _fetchT(url, init, timeoutMs) {
  const ctrl = new AbortController();
  const tid = setTimeout(function () { ctrl.abort(); }, timeoutMs || 75000);
  try {
    return await fetch(url, { ...init, signal: ctrl.signal });
  } catch (e) {
    if (e && e.name === 'AbortError')
      throw new Error('Operația a depășit timpul de așteptare. Reîncearcă.');
    throw e;
  } finally {
    clearTimeout(tid);
  }
}

async function api(path, opts = {}) {
  const headers = { 'Content-Type': 'application/json', ...(opts.headers || {}) };
  const t = getToken();
  if (t) headers['Authorization'] = 'Bearer ' + t;
  const r = await _fetchT(API + path, { ...opts, headers }, opts.timeoutMs);
  return _parseResp(r);
}

// Upload multipart (FormData) — fara Content-Type (browserul pune boundary-ul).
async function apiUpload(path, formData) {
  const headers = {};
  const t = getToken();
  if (t) headers['Authorization'] = 'Bearer ' + t;
  const r = await _fetchT(API + path, { method: 'POST', body: formData, headers });
  return _parseResp(r);
}

// Fetch un fisier protejat (sablon) ca blob autorizat -> object URL (token-ul NU apare in URL).
async function fetchBlobUrl(path) {
  const headers = {};
  const t = getToken();
  if (t) headers['Authorization'] = 'Bearer ' + t;
  const r = await fetch(API + path, { headers });
  if (!r.ok) throw new Error('HTTP ' + r.status);
  const b = await r.blob();
  return { url: URL.createObjectURL(b), type: b.type };
}

