const LAYER_NAME = { 1: 'Headers', 2: 'Continut', 3: 'LLM', 4: 'Strict' };

// AI category colors (informatie / sesizare / reclamatie / necunoscut)
const CAT_COLORS = { informatie: '#3b82f6', sesizare: '#f59e0b', reclamatie: '#ef4444', necunoscut: '#6b7280' };

// Care AI a procesat emailul (din ai_call_log: gemma local / Claude / corectat manual).
function aiModelBadge(e) {
  var r = e.ai_result || {};
  if (r.manual) return h('span', { className: 'badge', style: { background: 'var(--t3)', color: '#fff', textTransform: 'none' }, title: 'corectat manual' }, 'manual');
  var m = e.ai_model || r.model || (r.escalated ? 'claude' : null);
  if (!m) return h('span', { style: { color: 'var(--t3)' } }, '—');
  var ml = String(m).toLowerCase();
  if (ml.indexOf('gemma') >= 0) return h('span', { className: 'badge', style: { background: '#10b981', color: '#fff', textTransform: 'none' }, title: 'gemma local' }, 'gemma');
  if (ml.indexOf('claude') >= 0) return h('span', { className: 'badge', style: { background: '#3b82f6', color: '#fff', textTransform: 'none' }, title: m }, r.escalated ? 'Claude ↑' : 'Claude');
  return h('span', { className: 'badge', style: { background: 'var(--t2)', color: '#fff', textTransform: 'none' }, title: m }, String(m));
}

// Badge de status uniform pentru TOATE listele (Toate/Email/Carantinate/Spam) si modal.
// 'spam' (status derivat de backend) -> badge portocaliu b-quarantined cu text 'SPAM',
// identic cu verdictul din modal. Restul statusurilor: clasa b-<status> + text uppercase.
function statusBadge(status) {
  var s = status || '';
  if (s === 'spam') return h('span', { className: 'badge b-quarantined' }, 'SPAM');
  if (s === 'duplicate') return h('span', { className: 'badge b-duplicate', title: 'Oprit ca duplicat al unui email deja primit' }, 'Oprit: duplicat');
  return h('span', { className: 'badge b-' + s.replace('_', '-') }, s.toUpperCase());
}

// #rrggbb + alpha -> rgba() (pentru badge-uri flat theme-aware).
function hexA(hex, a) {
  var m = /^#?([0-9a-fA-F]{6})$/.exec(hex || '');
  if (!m) return hex;
  var n = parseInt(m[1], 16);
  return 'rgba(' + ((n >> 16) & 255) + ',' + ((n >> 8) & 255) + ',' + (n & 255) + ',' + a + ')';
}

// Badge categorie AI — stil flat (fill subtil + text colorat + bordură fină), sentence case.
function catBadge(cat, extra) {
  if (!cat) return null;
  var col = CAT_COLORS[cat] || CAT_COLORS.necunoscut;
  return h('span', { className: 'badge', style: Object.assign({ background: hexA(col, 0.14), color: col, borderColor: hexA(col, 0.34), textTransform: 'none' }, extra || {}) }, cat);
}

// Celulă dată compactă: ora sus, data dedesubt (ocupă mai puțină lățime decât string-ul inline).
function dateCell(iso) {
  if (!iso) return '';
  var d = new Date(iso);
  return h('div', { style: { lineHeight: 1.2 } }, [
    h('div', { key: 't', style: { fontSize: 12, color: 'var(--t2)', fontWeight: 600 } }, d.toLocaleTimeString('ro-RO', { hour: '2-digit', minute: '2-digit' })),
    h('div', { key: 'd', style: { fontSize: 11, color: 'var(--t3)' } }, d.toLocaleDateString('ro-RO'))
  ]);
}

// Procentul de confidență AI, colorat (verde/galben/roșu).
function confPct(res) {
  if (!res || res.confidence == null) return null;
  var c = res.confidence;
  return h('span', { key: 'c', style: { fontSize: 11, fontWeight: 600, color: c >= 0.75 ? 'var(--gn)' : c >= 0.5 ? 'var(--yw)' : 'var(--rd)' } }, Math.round(c * 100) + '%');
}

// Celulă Categorie: badge categorie + procent confidență alături (condensat, fără coloană separată).
function catCell(cat, ai_status, res) {
  if (!cat) return h('span', { style: { color: ai_status === 'error' ? 'var(--rd)' : 'var(--t3)', fontSize: 11 } }, ai_status === 'error' ? 'eroare' : 'neprocesat');
  return h('span', { style: { display: 'inline-flex', alignItems: 'center', gap: 6 } }, [catBadge(cat), confPct(res)]);
}

// ── Departamente (8) — slug -> etichetă afișată + culoare badge. Sincron cu department_classifier.py ──
const DEPT_LABELS = {
  suport_1: 'Suport 1', suport_2: 'Suport 2', suport_3: 'Suport 3', taxe_drum: 'Taxe de drum',
  contabilitate: 'Contabilitate', mobilitate: 'Mobilitate', recuperare_tva: 'Recuperare TVA', comercial: 'Comercial'
};
const DEPT_SLUGS = Object.keys(DEPT_LABELS);
const DEPT_COLORS = {
  suport_1: '#6b7280', suport_2: '#8b5cf6', suport_3: '#14b8a6', taxe_drum: '#f59e0b',
  contabilitate: '#10b981', mobilitate: '#3b82f6', recuperare_tva: '#ec4899', comercial: '#f97316'
};
function deptLabel(slug) { return DEPT_LABELS[slug] || slug; }
// Badge departament — același stil flat ca badge-ul de categorie, dar afișează ETICHETA.
function deptBadge(slug, extra) {
  if (!slug) return null;
  var col = DEPT_COLORS[slug] || DEPT_COLORS.suport_1;
  return h('span', { className: 'badge', style: Object.assign({ background: hexA(col, 0.14), color: col, borderColor: hexA(col, 0.34), textTransform: 'none', whiteSpace: 'nowrap' }, extra || {}) }, deptLabel(slug));
}
// Celulă Departament: badge + procent confidență (rule => fără procent, e 100% determinist).
function deptCell(slug, res) {
  if (!slug) return h('span', { style: { color: 'var(--t3)', fontSize: 11 } }, '—');
  var r = res || {};
  return h('span', { style: { display: 'inline-flex', alignItems: 'center', gap: 6 } },
    [deptBadge(slug), (r.model === 'rule' || r.model === 'manual') ? null : confPct(r)]);
}

// ── Asignare pe utilizator (OPS-2026-0131): cine se ocupa de email (din semnatura/fir CTS) ──
const ASG_COLOR = '#6366f1';
function asgPretty(email, name) {
  if (name && String(name).trim()) return String(name).trim();
  if (!email) return '';
  var lp = String(email).split('@')[0].replace(/[._-]+/g, ' ').trim();
  return lp.replace(/\b\w/g, function(c){ return c.toUpperCase(); });
}
function assigneeBadge(email, name) {
  if (!email) return null;
  return h('span', { className: 'badge', title: email, style: { background: hexA(ASG_COLOR, 0.14), color: ASG_COLOR, borderColor: hexA(ASG_COLOR, 0.34), textTransform: 'none', whiteSpace: 'nowrap' } }, asgPretty(email, name));
}
// Celula "Asignat" in liste: badge persoana, sau "review"/"—" (neasignat).
function assigneeCell(email, res) {
  var r = res || {};
  if (email) return assigneeBadge(email, r.assignee_name);
  if (r.needs_review) return h('span', { title: r.reason || 'De verificat manual', style: { color: 'var(--yw)', fontSize: 11, whiteSpace: 'nowrap' } }, '\u26a0 review');
  return h('span', { style: { color: 'var(--t3)', fontSize: 11 } }, '\u2014');
}

// ── Prioritate email (4 niveluri): 2=P2 Plăți (roșu) / 3=P3 Sesizare-Reclamație (ambră) /
//    4=P4 Documente (albastru) / 5=P5 General (gri). Sincron cu priority_classifier.py ──
function priNorm(p) {
  if (p == null || p === '') return null;
  var s = String(p).toUpperCase();
  if (s === 'P2' || s === '2') return '2';
  if (s === 'P3' || s === '3') return '3';
  if (s === 'P4' || s === '4') return '4';
  if (s === 'P5' || s === '5') return '5';
  return s;
}
const PRIORITY_LABELS = { '2': 'P2', '3': 'P3', '4': 'P4', '5': 'P5' };
const PRIORITY_COLORS = { '2': '#ef4444', '3': '#f59e0b', '4': '#3b82f6', '5': '#6b7280' };
const PRIORITY_FULL = { '2': 'P2 — Plăți', '3': 'P3 — Sesizare/Reclamație', '4': 'P4 — Documente', '5': 'P5 — General' };
function priorityLabel(p) { var n = priNorm(p); return PRIORITY_LABELS[n] || (n || ''); }
function priorityBadge(p, extra) {
  var n = priNorm(p);
  if (!n) return null;
  var col = PRIORITY_COLORS[n] || PRIORITY_COLORS['5'];
  var lbl = PRIORITY_LABELS[n] || n;
  return h('span', { className: 'badge', style: Object.assign({ background: hexA(col, 0.14), color: col, borderColor: hexA(col, 0.34), textTransform: 'none', whiteSpace: 'nowrap', fontWeight: (n === '2' ? 700 : 500) }, extra || {}) }, n === '2' ? '\u26A0 ' + lbl : lbl);
}
// Badge prioritate CLIENT (CRM, scala separata 1=urgent / 2=normal) — decuplat de scala email P2/P3.
function clientPriorityBadge(p) {
  if (p == null || p === '') return null;
  var urg = String(p) === '1';
  var col = urg ? '#ef4444' : '#6b7280';
  var lbl = urg ? 'Urgent' : 'Normal';
  return h('span', { className: 'badge', style: { background: hexA(col, 0.14), color: col, borderColor: hexA(col, 0.34), textTransform: 'none', whiteSpace: 'nowrap', fontWeight: urg ? 700 : 500 } }, urg ? '\u26A0 ' + lbl : lbl);
}
// Celula Prioritate: badge + procent scor (rule/manual => fara procent).
function priorityCell(p, res) {
  if (!p) return h('span', { style: { color: 'var(--t3)', fontSize: 11 } }, '—');
  var r = res || {};
  return h('span', { style: { display: 'inline-flex', alignItems: 'center', gap: 6 } },
    [priorityBadge(p), (r.model === 'rule' || r.model === 'manual' || r.score == null) ? null : h('span', { style: { fontSize: 11, color: 'var(--t3)' } }, Math.round(r.score * 100) + '%')]);
}

// Bară de paginare compactă, fixată jos: Prima / −5 / Înapoi / „Pagina X / Y" / Înainte / +5 / Ultima.
// Folosită identic în lista de emailuri și în Spam. setPage primește valoarea finală (page e curent în render).
function pager(page, totalPages, setPage) {
  var bs = { padding: '4px 9px', fontSize: 12 };
  return h('div', { style: { flexShrink: 0, marginTop: 8, paddingTop: 7, borderTop: '1px solid var(--bd,#222)', display: 'flex', gap: 5, justifyContent: 'center', alignItems: 'center', flexWrap: 'wrap' } }, [
    h('button', { key: 'first', className: 'btn secondary', style: bs, title: 'Prima pagină', disabled: page <= 1, onClick: function(){ setPage(1); } }, '« Prima'),
    h('button', { key: 'm5', className: 'btn secondary', style: bs, title: 'Înapoi 5 pagini', disabled: page <= 1, onClick: function(){ setPage(Math.max(1, page - 5)); } }, '−5'),
    h('button', { key: 'p', className: 'btn secondary', style: bs, disabled: page <= 1, onClick: function(){ setPage(Math.max(1, page - 1)); } }, '‹ Înapoi'),
    h('span', { key: 's', style: { padding: '4px 12px', color: 'var(--t2)', fontSize: 12, whiteSpace: 'nowrap' } }, 'Pagina ' + page + ' / ' + totalPages),
    h('button', { key: 'n', className: 'btn secondary', style: bs, disabled: page >= totalPages, onClick: function(){ setPage(Math.min(totalPages, page + 1)); } }, 'Înainte ›'),
    h('button', { key: 'p5', className: 'btn secondary', style: bs, title: 'Înainte 5 pagini', disabled: page >= totalPages, onClick: function(){ setPage(Math.min(totalPages, page + 5)); } }, '+5'),
    h('button', { key: 'last', className: 'btn secondary', style: bs, title: 'Ultima pagină', disabled: page >= totalPages, onClick: function(){ setPage(totalPages); } }, 'Ultima »')
  ]);
}

// Badge Status CTS: ce a ajuns in CTS si DE CE inca nu (din obiectul `fc` derivat de backend).
function fcBadge(fc) {
  if (!fc) return h('span', { style: { color: 'var(--t3)', fontSize: 11 } }, '—');
  var cls = { sent: 'b-clean', ready: 'b-pending', send_error: 'b-strict',
              error_nova: 'b-strict', stopped: 'b-ndr', in_progress: 'b-pending' }[fc.state] || 'b-ndr';
  var txt = fc.state === 'sent' ? 'Trimis în CTS' : (fc.reason || 'Netrimis');
  var title = [fc.label, fc.reason, fc.detail, (fc.sent_at ? 'la ' + new Date(fc.sent_at).toLocaleString('ro-RO') : null),
               (fc.attempts ? fc.attempts + ' încercări' : null)].filter(Boolean).join(' · ');
  return h('span', { className: 'badge ' + cls, title: title, style: { textTransform: 'none' } }, txt);
}

// Badge „Solved→CTS" — mailuri automate care pleaca/au plecat marcate SOLVED spre CTS.
//   plin (verde, ✓) = cts_mark_solved -> a plecat efectiv ca solved (confirmat de CTS la update_emails)
//   outline (dashed) = cts_auto_solved_match -> se potriveste regulii acum, urmeaza sa plece ca solved
function solvedCtsBadge(e, key) {
  if (!e) return null;
  var sent = !!e.cts_mark_solved;
  var pend = !sent && !!e.cts_auto_solved_match;
  if (!sent && !pend) return null;
  var style = sent
    ? { textTransform: 'none', background: '#E6F4EA', color: '#1a7f37', border: '0.5px solid #9BD3AC', marginLeft: 4 }
    : { textTransform: 'none', background: 'transparent', color: '#1a7f37', border: '0.5px dashed #9BD3AC', marginLeft: 4 };
  var title = sent ? 'A plecat în CTS marcat ca SOLVED (mail automat)'
                   : 'Mail automat — urmează să plece în CTS marcat ca SOLVED';
  return h('span', { key: key || 'sv', className: 'badge', title: title, style: style },
           (sent ? '✓ ' : '') + 'Solved');
}

// ════════════════════════════════════════════════════════════════════════════
// Modul „Mail-uri CTS" — comparatie ground-truth CTS vs clasificare Cargo360 (training)
// Read-only fata de fluxul curent: doar afiseaza & compara. Vezi app/api/v1/cts_training.py
// ════════════════════════════════════════════════════════════════════════════
// Modal pt emailul TRIMIS (reply colege) — vizualizare IDENTICĂ cu modalul „PRIMIT"
// (shell .em2, corp randat la fel), dar fără acțiuni de clasificare: doar flag TRIMIS,
// corp + atașamente, navigare next/prev și (opțional) comparație cu sugestia AI.
// Corpul vine LAZY din CTS prin /cts-training/sent-body (cache pe rând). Strict în Mail-uri CTS.
function ctsParseAtts(v) {
  try { return Array.isArray(v) ? v : (v ? JSON.parse(v) : []); } catch (e) { return []; }
}
// Badge colorat pentru statusul CTS al unui mail: new=albastru, in progress=galben,
// solved=verde, deleted=gri. Tolerează variații de scriere (in_progress / inprogress).
function ctsStatusBadge(status, key) {
  if (!status) return null;
  var s = String(status).toLowerCase().replace(/[_\s]+/g, ' ').trim();
  var PAL = {
    'new':         { fill: '#E7EFF8', txt: '#185FA5', bd: '#A9C6E5', label: 'new' },
    'in progress': { fill: '#FAEEDA', txt: '#854F0B', bd: '#EF9F27', label: 'in progress' },
    'solved':      { fill: '#E6F4EA', txt: '#1a7f37', bd: '#9BD3AC', label: 'solved' },
    'deleted':     { fill: '#F2F2EF', txt: '#5F5E5A', bd: 'rgba(0,0,0,0.15)', label: 'deleted' }
  };
  var p = PAL[s] || { fill: '#F2F2EF', txt: '#5F5E5A', bd: 'rgba(0,0,0,0.15)', label: s };
  return h('span', { key: key || 'st', title: 'Status CTS: ' + p.label, className: 'badge',
    style: { textTransform: 'none', background: p.fill, color: p.txt, border: '0.5px solid ' + p.bd } }, p.label);
}
function CtsSentModal({ item, items, index, onClose, onNext, onPrev }) {
  var it = item || {};
  const [body, setBody] = useState(null);   // {reply_text, attachments, available} | null = se încarcă
  const [err, setErr] = useState('');
  const [gen, setGen] = useState(null);     // sugestie AI generată acum (pe emailul primit pereche)
  const [genBusy, setGenBusy] = useState(false);
  var logId = it.cts_email_log_id;
  var navItems = items || [];
  var idx = (index == null) ? -1 : index;
  var canPrev = idx > 0;
  var canNext = idx > -1 && idx < navItems.length - 1;
  useEffect(function() {
    var cancelled = false;
    setBody(null); setErr(''); setGen(null); setGenBusy(false);
    var fallback = { reply_text: it.cts_reply_text || it.cts_reply_html || '',
                     attachments: ctsParseAtts(it.cts_attachments),
                     available: !!(it.cts_reply_text || it.cts_reply_html) };
    if (!logId) {
      setBody(fallback);
    } else {
      api('/cts-training/sent-body?log_id=' + encodeURIComponent(logId)).then(function(r) {
        if (cancelled) return;
        setBody({ reply_text: (r && r.reply_text) || fallback.reply_text,
                  attachments: (r && r.attachments && r.attachments.length) ? r.attachments : fallback.attachments,
                  available: !!(r && r.available) || fallback.available,
                  paired: (r && r.paired_received) || null });
      }).catch(function(e) { if (!cancelled) { setErr(String(e)); setBody(fallback); } });
    }
    var onKey = function(e) {
      if (e.key === 'Escape') onClose();
      else if (e.key === 'ArrowRight' && canNext && onNext) onNext();
      else if (e.key === 'ArrowLeft' && canPrev && onPrev) onPrev();
    };
    document.body.style.overflow = 'hidden';
    window.addEventListener('keydown', onKey);
    return function() { cancelled = true; window.removeEventListener('keydown', onKey); document.body.style.overflow = ''; };
  }, [logId]);

  function fmtSize(n){ if(!n && n!==0) return ''; if(n<1024) return n+' B'; if(n<1048576) return (n/1024).toFixed(0)+' KB'; return (n/1048576).toFixed(1)+' MB'; }
  var dateStr = it.cts_solved_at || it.cts_date || it.cts_reply_at || null;
  var atts = (body && body.attachments) ? body.attachments : ctsParseAtts(it.cts_attachments);
  var replyText = body ? (body.reply_text || '') : '';
  var isHtml = /<[a-z!\/][^>]*>/i.test(replyText);
  var sandboxed = (body && isHtml && replyText) ? buildEmailSrcDoc(replyText) : '';
  var paired = (body && body.paired) || null;   // emailul PRIMIT pereche (msid/subiect) + sugestia AI de pe el
  var aiSugg = (gen && gen.ai_autoreply) || (paired && paired.ai_autoreply);
  var aiConf = (gen && gen.ai_autoreply_confidence != null) ? gen.ai_autoreply_confidence
             : (paired ? paired.ai_autoreply_confidence : null);
  // generează sugestia AI de reply pe emailul PRIMIT pereche (reutilizează endpointul existent)
  function genSuggestion() {
    if (!paired || !paired.email_id || genBusy) return;
    setGenBusy(true);
    api('/ai/autoreply/' + paired.email_id + '/generate', { method: 'POST' }).then(function(r) {
      setGenBusy(false);
      if (r && r.ai_autoreply) {
        setGen({ ai_autoreply: r.ai_autoreply, ai_autoreply_confidence: r.ai_autoreply_confidence,
                 ai_autoreply_status: r.ai_autoreply_status });
        mgToast('success', 'Sugestie AI generată');
      } else {
        Swal.fire({ icon: 'error', title: 'Eroare', text: (r && r.detail) || 'Generare eșuată', background: 'var(--bg2,#0e131c)', color: 'var(--tx,#e6edf3)' });
      }
    }).catch(function(e) { setGenBusy(false); Swal.fire({ icon: 'error', title: 'Eroare', text: String((e && e.message) || e), background: 'var(--bg2,#0e131c)', color: 'var(--tx,#e6edf3)' }); });
  }
  // snippet din corpul emailului primit pereche (text simplu, fără HTML)
  var pairedSnippet = '';
  if (paired && paired.body_text) {
    pairedSnippet = String(paired.body_text).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 600);
  }

  // ── conținutul principal (corpul emailului trimis) ──────────────────────────
  var mainContent;
  if (!body) {
    mainContent = h('div', { style: { padding: 22, color: 'var(--t3)', fontSize: 13 } }, 'Se încarcă corpul din CTS…');
  } else if (!replyText) {
    mainContent = h('div', { style: { padding: 22, color: 'var(--t3)', fontStyle: 'italic', fontSize: 13 } },
      err ? ('Nu am putut aduce corpul din CTS: ' + err) : 'Corpul acestui email trimis nu este disponibil în CTS.');
  } else if (isHtml) {
    mainContent = h('div', { style: { height: '100%' } },
      h('iframe', { sandbox: '', srcDoc: sandboxed, title: 'Corp email trimis', style: { width: '100%', height: '100%', minHeight: '68vh', border: 0, background: '#fff' } }));
  } else {
    mainContent = h('pre', { className: 'body-text' }, replyText);
  }

  var metaRow = function(k, v) { return h('div', { key: k, style: { fontSize: 12.5, lineHeight: 1.5, wordBreak: 'break-word' } }, [
    h('span', { key: 'k', style: { color: '#8A8A82', marginRight: 6 } }, k), h('span', { key: 'v', style: { color: '#2C2C2A' } }, v || '—')]); };

  return h('div', { className: 'modal-bg', onMouseDown: function(e) { if (e.target === e.currentTarget) onClose(); } },
    h('div', { className: 'em2', onClick: function(e) { e.stopPropagation(); } }, [
      // HEADER
      h('div', { key: 'head', style: { display: 'flex', alignItems: 'flex-start', gap: 14, padding: '14px 18px', borderBottom: '0.5px solid rgba(0,0,0,0.12)' } }, [
        h('div', { key: 'ti', style: { flex: 1, minWidth: 0 } }, [
          h('div', { key: 'b', style: { display: 'inline-flex', alignItems: 'center', gap: 8, marginBottom: 5, flexWrap: 'wrap' } }, [
            h('span', { key: 'bd', className: 'badge', style: { textTransform: 'none', background: hexA('#2ea043', 0.12), color: '#1a7f37', border: '1px solid ' + hexA('#2ea043', 0.35) } }, '↑ TRIMIS de noi'),
            h('span', { key: 'n', style: { fontSize: 11, color: '#8A8A82' } }, 'reply coleg — doar vizualizare, fără încadrare')
          ]),
          h('div', { key: 's', style: { fontSize: 16, fontWeight: 600, color: '#2C2C2A', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }, title: it.subject || '' }, it.subject || '(fără subiect)')
        ]),
        h('div', { key: 'nav', style: { display: 'flex', alignItems: 'center', gap: 6, flexShrink: 0 } }, [
          h('button', { key: 'p', disabled: !canPrev, onClick: canPrev ? onPrev : null, title: 'Anterior (←)', style: { width: 30, height: 30, borderRadius: 8, border: '0.5px solid rgba(0,0,0,0.15)', background: '#fff', color: '#5F5E5A', fontSize: 15, cursor: canPrev ? 'pointer' : 'default', opacity: canPrev ? 1 : 0.35, padding: 0 } }, '←'),
          h('button', { key: 'nx', disabled: !canNext, onClick: canNext ? onNext : null, title: 'Următor (→)', style: { width: 30, height: 30, borderRadius: 8, border: '0.5px solid rgba(0,0,0,0.15)', background: '#fff', color: '#5F5E5A', fontSize: 15, cursor: canNext ? 'pointer' : 'default', opacity: canNext ? 1 : 0.35, padding: 0 } }, '→'),
          h('button', { key: 'x', 'aria-label': 'Închide', title: 'Închide (ESC)', onClick: onClose, style: { width: 30, height: 30, borderRadius: 8, border: '0.5px solid rgba(0,0,0,0.15)', background: '#fff', color: '#5F5E5A', fontSize: 16, lineHeight: 1, padding: 0, cursor: 'pointer' } }, '×')
        ])
      ]),
      // BODY (side + main)
      h('div', { key: 'body', className: 'em2-body2' }, [
        h('div', { key: 'side', className: 'em2-side' }, [
          h('div', { key: 'meta', style: { background: '#fff', border: '0.5px solid rgba(0,0,0,0.10)', borderRadius: 10, padding: '11px 12px', display: 'flex', flexDirection: 'column', gap: 6 } }, [
            h('div', { key: 'l', style: { fontSize: 10.5, fontWeight: 700, color: '#8A8A82', textTransform: 'uppercase', letterSpacing: '0.04em' } }, 'Email'),
            metaRow('De la:', it.cts_from_email),
            metaRow('Către:', it.cts_to_email),
            metaRow('Data:', dateStr ? new Date(dateStr).toLocaleString('ro-RO') : null),
            it.cts_status ? h('div', { key: 'st', style: { fontSize: 12.5, lineHeight: 1.5, display: 'flex', alignItems: 'center', gap: 6 } }, [
              h('span', { key: 'k', style: { color: '#8A8A82' } }, 'Status CTS:'), ctsStatusBadge(it.cts_status, 'b')
            ]) : null
          ]),
          // Emailul PRIMIT căruia i s-a răspuns (legat pe msid sau pe expeditor+subiect)
          h('div', { key: 'rcv', style: { background: '#fff', border: '0.5px solid rgba(0,0,0,0.10)', borderRadius: 10, padding: '11px 12px', display: 'flex', flexDirection: 'column', gap: 6 } }, [
            h('div', { key: 'l', style: { fontSize: 10.5, fontWeight: 700, color: '#8A8A82', textTransform: 'uppercase', letterSpacing: '0.04em' } }, 'Email primit (la care s-a răspuns)'),
            !body
              ? h('div', { key: 'v', style: { fontSize: 11.5, color: '#8A8A82', fontStyle: 'italic' } }, 'Se încarcă…')
              : (paired
                ? [
                    h('div', { key: 'sub', style: { fontSize: 12.5, fontWeight: 600, color: '#2C2C2A', wordBreak: 'break-word' } }, paired.subject || '(fără subiect)'),
                    metaRow('De la:', paired.from_name ? (paired.from_name + ' <' + (paired.from_address || '') + '>') : paired.from_address),
                    metaRow('Data:', paired.received_at ? new Date(paired.received_at).toLocaleString('ro-RO') : null),
                    pairedSnippet ? h('div', { key: 'sn', style: { fontSize: 11.5, lineHeight: 1.5, color: '#5F5E5A', whiteSpace: 'pre-wrap', wordBreak: 'break-word', maxHeight: 160, overflow: 'auto', background: '#FAFAF7', borderRadius: 6, padding: '6px 8px' } }, pairedSnippet) : null,
                    h('div', { key: 'lk', style: { fontSize: 10.5, color: '#8A8A82' } }, '#' + paired.email_id + ' · legat ' + (paired.match_by === 'msid' ? 'pe Message-ID' : 'pe expeditor + subiect'))
                  ]
                : h('div', { key: 'v', style: { fontSize: 11.5, color: '#8A8A82', fontStyle: 'italic' } },
                    'Nu am găsit emailul primit corespunzător (fără Message-ID și fără potrivire pe expeditor + subiect, sau neîncă importat în Cargo360).'))
          ]),
          // Comparație: ce a SUGERAT AI (pe emailul primit) vs ce a TRIMIS colegul (dreapta)
          h('div', { key: 'cmp', style: { background: '#fff', border: '0.5px solid rgba(0,0,0,0.10)', borderRadius: 10, padding: '11px 12px', display: 'flex', flexDirection: 'column', gap: 6 } }, [
            h('div', { key: 'l', style: { fontSize: 10.5, fontWeight: 700, color: '#8A8A82', textTransform: 'uppercase', letterSpacing: '0.04em' } }, 'Sugestie AI vs reply trimis'),
            !body
              ? h('div', { key: 'v', style: { fontSize: 11.5, color: '#8A8A82', fontStyle: 'italic' } }, 'Se încarcă…')
              : (aiSugg
                ? [
                    h('div', { key: 'cf', style: { fontSize: 10.5, color: '#8A8A82' } }, (gen ? 'AI a sugerat acum' : 'AI ar fi sugerat') + (aiConf != null ? (' · încredere ' + Math.round(aiConf * 100) + '%') : '') + ':'),
                    h('div', { key: 'v', style: { fontSize: 12, lineHeight: 1.5, color: '#2C2C2A', whiteSpace: 'pre-wrap', wordBreak: 'break-word', maxHeight: 200, overflow: 'auto', background: '#FAFAF7', borderRadius: 6, padding: '6px 8px' } }, aiSugg),
                    h('div', { key: 'h', style: { fontSize: 10.5, color: '#8A8A82' } }, '↔ compară cu reply-ul real al colegului (dreapta)'),
                    paired && paired.email_id ? h('button', { key: 'rg', disabled: genBusy, onClick: genSuggestion, style: { marginTop: 2, padding: '5px 10px', fontSize: 11.5, fontWeight: 500, color: '#2C2C2A', background: '#fff', border: '0.5px solid rgba(0,0,0,0.15)', borderRadius: 8, cursor: genBusy ? 'default' : 'pointer', opacity: genBusy ? 0.6 : 1 } }, genBusy ? 'Se generează…' : '↻ Regenerează sugestia') : null
                  ]
                : (paired && paired.email_id
                  ? [
                      h('div', { key: 'v', style: { fontSize: 11.5, color: '#8A8A82', fontStyle: 'italic' } }, 'AI nu a generat încă o sugestie de reply pentru emailul primit (#' + paired.email_id + ').'),
                      h('button', { key: 'g', disabled: genBusy, onClick: genSuggestion, style: { marginTop: 2, padding: '6px 12px', fontSize: 12, fontWeight: 500, color: '#fff', background: '#1a7f37', border: '0.5px solid #1a7f37', borderRadius: 8, cursor: genBusy ? 'default' : 'pointer', opacity: genBusy ? 0.6 : 1 } }, genBusy ? 'Se generează…' : '✨ Generează sugestia de reply')
                    ]
                  : h('div', { key: 'v', style: { fontSize: 11.5, color: '#8A8A82', fontStyle: 'italic' } }, 'Fără emailul primit pereche nu se poate genera o sugestie AI.')))
          ]),
          atts.length ? h('div', { key: 'att', style: { background: '#fff', border: '0.5px solid rgba(0,0,0,0.10)', borderRadius: 10, padding: '11px 12px', display: 'flex', flexDirection: 'column', gap: 8 } }, [
            h('div', { key: 'l', style: { fontSize: 10.5, fontWeight: 700, color: '#8A8A82', textTransform: 'uppercase', letterSpacing: '0.04em' } }, 'Atașamente · ' + atts.length),
            h('div', { key: 'list', style: { display: 'flex', flexDirection: 'column', gap: 6 } }, atts.map(function(a, i) {
              return h('div', { key: i, title: (a.mime || ''), style: { display: 'flex', alignItems: 'center', gap: 6, padding: '5px 8px', border: '0.5px solid rgba(0,0,0,0.12)', borderRadius: 8, fontSize: 12, background: '#FAFAF7' } }, [
                h('span', { key: 'i', style: { color: '#8A8A82' } }, '📎'),
                h('span', { key: 'n', style: { color: '#2C2C2A', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' } }, (a.name || ('atașament ' + (i + 1)))),
                a.filesize ? h('span', { key: 's', style: { color: '#8A8A82', flexShrink: 0 } }, fmtSize(a.filesize)) : null
              ]);
            })),
            h('div', { key: 'note', style: { fontSize: 10.5, color: '#8A8A82', fontStyle: 'italic' } }, 'Conținutul fișierelor nu e disponibil prin gateway (doar nume/tip/mărime).')
          ]) : null
        ]),
        h('div', { key: 'main', className: 'em2-main2' },
          h('div', { key: 'c', className: 'em2-content' }, mainContent))
      ]),
      // FOOTER nav
      h('div', { key: 'foot', style: { display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 10, padding: '12px 16px', borderTop: '0.5px solid rgba(0,0,0,0.12)', background: '#FAFAF7' } }, [
        h('button', { key: 'p', disabled: !canPrev, onClick: canPrev ? onPrev : null, style: { padding: '7px 14px', borderRadius: 8, border: '0.5px solid rgba(0,0,0,0.15)', background: '#fff', color: '#2C2C2A', fontSize: 13, cursor: canPrev ? 'pointer' : 'default', opacity: canPrev ? 1 : 0.4 } }, '← Anterior'),
        (idx > -1 && navItems.length) ? h('span', { key: 'c', style: { fontSize: 12, color: '#8A8A82' } }, (idx + 1) + ' / ' + navItems.length) : null,
        h('button', { key: 'n', disabled: !canNext, onClick: canNext ? onNext : null, style: { padding: '7px 14px', borderRadius: 8, border: '0.5px solid rgba(0,0,0,0.15)', background: '#fff', color: '#2C2C2A', fontSize: 13, cursor: canNext ? 'pointer' : 'default', opacity: canNext ? 1 : 0.4 } }, 'Următor →')
      ])
    ])
  );
}

function CtsTrainingPanel() {
  const [stats, setStats] = useState(null);
  const [data, setData] = useState({ items: [], total: 0, page: 1, page_size: 50 });
  const [loading, setLoading] = useState(true);
  const [page, setPage] = useState(1);
  const [onlyMismatch, setOnlyMismatch] = useState(false);
  const [deptF, setDeptF] = useState('');
  const [deptFrom, setDeptFrom] = useState('');
  const [deptTo, setDeptTo] = useState('');
  const [dateFrom, setDateFrom] = useState('');
  const [dateTo, setDateTo] = useState('');
  const [axis, setAxis] = useState('');
  const [searchId, setSearchId] = useState('');
  const [assigneeF, setAssigneeF] = useState('');       // utilizator = assignee-ul CTS (adevar de teren)
  const [statusF, setStatusF] = useState('');           // status CTS: new / in progress / solved
  const [assigneeList, setAssigneeList] = useState([]);
  const [syncing, setSyncing] = useState(false);
  const [cfg, setCfg] = useState(null);
  const [selectedId, setSelectedId] = useState(null);   // email_id deschis în modalul de email (ca pe pagina Emailuri)
  const [sentDetail, setSentDetail] = useState(null);   // rândul CTS TRIMIS deschis în modalul propriu (corp + atașamente)
  const [dirTab, setDirTab] = useState('received');     // tab Direcție: 'received' (PRIMIT, default) | 'sent' (TRIMIS)

  function loadStats(df, dt, dF, dFr, dTo) {
    var qs = [];
    var _df = df !== undefined ? df : dateFrom;
    var _dt = dt !== undefined ? dt : dateTo;
    var _dF = dF !== undefined ? dF : deptF;
    var _dFr = dFr !== undefined ? dFr : deptFrom;
    var _dTo = dTo !== undefined ? dTo : deptTo;
    if (_dF) qs.push('department=' + encodeURIComponent(_dF));
    if (_dFr) qs.push('dept_from=' + encodeURIComponent(_dFr));
    if (_dTo) qs.push('dept_to=' + encodeURIComponent(_dTo));
    if (_df) qs.push('date_from=' + encodeURIComponent(_df));
    if (_dt) qs.push('date_to=' + encodeURIComponent(_dt));
    if (assigneeF) qs.push('assignee=' + encodeURIComponent(assigneeF));
    if (statusF) qs.push('status=' + encodeURIComponent(statusF));
    api('/cts-training/stats' + (qs.length ? '?' + qs.join('&') : '')).then(setStats).catch(function(){});
  }
  function loadCfg() { api('/cts-training/sync-config').then(setCfg).catch(function(){}); }
  function loadList() {
    setLoading(true);
    var qs = ['page=' + page, 'page_size=50', 'direction=' + dirTab];
    if (onlyMismatch && dirTab === 'received') qs.push('only_mismatch=1');
    if (deptF) qs.push('department=' + encodeURIComponent(deptF));
    if (deptFrom) qs.push('dept_from=' + encodeURIComponent(deptFrom));
    if (deptTo) qs.push('dept_to=' + encodeURIComponent(deptTo));
    if (dateFrom) qs.push('date_from=' + encodeURIComponent(dateFrom));
    if (dateTo) qs.push('date_to=' + encodeURIComponent(dateTo));
    if (axis) qs.push('axis=' + encodeURIComponent(axis));
    if (searchId.trim()) qs.push('search_id=' + encodeURIComponent(searchId.trim()));
    if (assigneeF) qs.push('assignee=' + encodeURIComponent(assigneeF));
    if (statusF) qs.push('status=' + encodeURIComponent(statusF));
    api('/cts-training/list?' + qs.join('&')).then(function(d){ setData(d); setLoading(false); })
      .catch(function(){ setLoading(false); });
  }
  useEffect(function(){ loadStats(); loadCfg(); }, []);
  useEffect(function(){ api('/cts-training/assignees').then(function(d){ setAssigneeList(d.assignees || []); }).catch(function(){}); }, []);
  useEffect(function(){ setPage(1); }, [onlyMismatch, deptF, deptFrom, deptTo, dateFrom, dateTo, axis, dirTab, searchId, assigneeF, statusF]);
  useEffect(function(){ loadList(); loadStats(); }, [page, onlyMismatch, deptF, deptFrom, deptTo, dateFrom, dateTo, axis, dirTab, searchId, assigneeF, statusF]);

  function doSync() {
    setSyncing(true);
    api('/cts-training/sync', { method: 'POST' }).then(function(r){
      setSyncing(false);
      if (r && r.ok) { mgToast('success', 'Sincronizat: ' + r.inserted + ' noi, ' + r.updated + ' actualizate'); loadStats(); loadList(); }
      else { mgToast('info', (r && r.reason) || 'Sync indisponibil'); }
    }).catch(function(){ setSyncing(false); mgToast('error', 'Eroare la sincronizare'); });
  }
  // Re-sync rolling 24h: prinde emailurile pe care CTS le-a (re)incadrat dupa receptie (catch).
  function doSyncRecent() {
    setSyncing(true);
    api('/cts-training/sync-recent?hours=24', { method: 'POST' }).then(function(r){
      if (r && r.started) {
        // Sync ruleaza in fundal (nu mai blocheaza / nu mai da timeout). Reimprospatam de cateva ori.
        mgToast('success', (r.message || 'Sync pornit in fundal.') + ' Se actualizeaza...');
        setTimeout(function(){ loadStats(); loadList(); }, 10000);
        setTimeout(function(){ loadStats(); loadList(); }, 30000);
        setTimeout(function(){ loadStats(); loadList(); setSyncing(false); }, 60000);
        return;
      }
      setSyncing(false);
      if (r && r.ok) { mgToast('success', 'Ultimele 24h: ' + r.inserted + ' noi, ' + r.updated + ' actualizate, ' + (r.changed || 0) + ' re-incadrate de CTS'); loadStats(); loadList(); }
      else { mgToast('info', (r && r.reason) || 'Sync indisponibil'); }
    }).catch(function(){ setSyncing(false); mgToast('error', 'Eroare la sincronizare'); });
  }

  function rate(v) { return v == null ? '—' : (v + '%'); }
  function rateColor(v) { return v == null ? 'var(--t3)' : (v >= 85 ? 'var(--gn)' : v >= 70 ? 'var(--yw)' : 'var(--rd)'); }

  function statCard(title, val, sub, color) {
    return h('div', { className: 'card', style: { flex: '1 1 150px', minWidth: 140, padding: '12px 15px', borderTop: '3px solid ' + (color || '#30363d') } }, [
      h('div', { key: 't', style: { fontSize: 10, color: 'var(--t3)', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '.06em' } }, title),
      h('div', { key: 'v', style: { fontSize: 24, fontWeight: 800, lineHeight: 1.15, marginTop: 5 } }, val),
      sub ? h('div', { key: 's', style: { fontSize: 11, color: 'var(--t3)', marginTop: 3 } }, sub) : null
    ]);
  }

  // celula comparativa: badge MG -> badge CTS + bifa/x; fundal rosu la divergenta
  function compCell(aiNode, ctsNode, match, ctsUnmapped) {
    var bg = match === false ? hexA('#ef4444', 0.10) : 'transparent';
    var bd = match === false ? '1px solid ' + hexA('#ef4444', 0.40) : '1px solid transparent';
    return h('div', { style: { display: 'flex', alignItems: 'center', gap: 6, flexWrap: 'wrap', padding: '3px 6px', borderRadius: 6, background: bg, border: bd } }, [
      aiNode || h('span', { key: 'a', style: { color: 'var(--t3)', fontSize: 11 } }, '—'),
      h('span', { key: 'ar', style: { color: 'var(--t3)', fontSize: 12 } }, '→'),
      ctsNode || h('span', { key: 'c', style: { color: 'var(--t3)', fontSize: 11 } }, '—'),
      ctsUnmapped ? h('span', { key: 'u', title: 'valoare CTS nemapata pe taxonomia Cargo360', style: { color: 'var(--yw)', fontSize: 11 } }, '?') : null,
      match === true ? h('span', { key: 'ok', style: { color: 'var(--gn)', fontWeight: 700, fontSize: 13 } }, '✓')
        : (match === false ? h('span', { key: 'x', style: { color: 'var(--rd)', fontWeight: 700, fontSize: 13 } }, '✗') : null)
    ]);
  }

  function replyCell(it) {
    function box(lbl, txt, muted) {
      return h('div', { style: { marginBottom: 4 } }, [
        h('span', { key: 'l', style: { fontSize: 10, fontWeight: 700, color: 'var(--t3)', marginRight: 4 } }, lbl),
        h('span', { key: 't', title: txt || '', style: { fontSize: 11, color: muted ? 'var(--t3)' : 'var(--t2)' } },
          txt ? (txt.length > 120 ? txt.slice(0, 120) + '…' : txt) : '—')
      ]);
    }
    return h('div', { style: { minWidth: 220, maxWidth: 360 } }, [
      box('COLEGI', it.cts_reply_text, false),
      box('IRIS', it.ai_autoreply, true)
    ]);
  }

  var st = stats || {};
  var catS = st.category || {}; var depS = st.department || {}; var asgS = st.assignee || {};
  var confusion = st.confusion || [];
  var totalPages = Math.max(1, Math.ceil((data.total || 0) / (data.page_size || 50)));

  var headerCards = h('div', { key: 'cards', style: { display: 'flex', gap: 12, flexWrap: 'wrap', marginBottom: 14 } }, [
    statCard('Potrivire categorie', rate(catS.match_rate), (catS.matched || 0) + ' / ' + (catS.comparable || 0) + ' comparabile', rateColor(catS.match_rate)),
    statCard('Potrivire departament', rate(depS.match_rate), (depS.matched || 0) + ' / ' + (depS.comparable || 0) + ' comparabile', rateColor(depS.match_rate)),
    statCard('Potrivire dept. fără Suport 1', rate(depS.match_rate_excl_suport1), (depS.matched_excl_suport1 || 0) + ' / ' + (depS.comparable || 0) + ' comparabile', rateColor(depS.match_rate_excl_suport1)),
    statCard('Potrivire asignare', rate(asgS.match_rate), (asgS.matched || 0) + ' / ' + (asgS.comparable || 0) + ' comparabile', rateColor(asgS.match_rate)),
    statCard('Trimise de noi', (st.sent_count || 0), 'reply colegi · excluse din statistici', 'var(--t2)'),
    statCard('Total emailuri CTS', (st.total || 0), (st.only_in_cts || 0) + ' doar in CTS', 'var(--tx)')
  ]);

  // Divergențele MG→CTS s-au mutat în Setări → Prompturi AI (lângă regenerarea prompturilor),
  // ca semnal de „corectură" pe care se bazează regenerarea. Aici nu le mai afișăm.

  var syncActive = cfg && cfg.active;
  var syncNote = cfg ? (cfg.active ? 'Sync activ (' + (cfg.source_mode || '') + ')'
    : (cfg.source_configured ? 'Sursa configurata, sync dezactivat' : 'Sursa CTS neconfigurata — in asteptarea grant-ului (outbox)')) : '';

  var deptOpts = [h('option', { key: '', value: '' }, '— orice —')].concat(DEPT_SLUGS.map(function(s){ return h('option', { key: s, value: s }, DEPT_LABELS[s]); }));
  var filters = h('div', { key: 'flt', style: { display: 'flex', gap: 8, alignItems: 'center', flexWrap: 'wrap', marginBottom: 10 } }, [
    h('label', { key: 'm', style: { display: 'flex', alignItems: 'center', gap: 6, fontSize: 13, cursor: 'pointer' } }, [
      h('input', { key: 'i', type: 'checkbox', checked: onlyMismatch, onChange: function(e){ setOnlyMismatch(e.target.checked); } }),
      'Doar divergente'
    ]),
    h('span', { key: 'sep0', style: { color: 'var(--bd)', fontSize: 18, lineHeight: 1, userSelect: 'none' } }, '|'),
    h('input', { key: 'sid', type: 'text', inputMode: 'numeric', placeholder: 'Caută ID mail…', value: searchId,
      className: 'btn secondary', style: { padding: '6px 10px', width: 140, fontFamily: 'inherit', fontSize: 13 },
      onChange: function(e){ setSearchId(e.target.value.replace(/[^0-9]/g, '')); } }),
    h('span', { key: 'sep1', style: { color: 'var(--bd)', fontSize: 18, lineHeight: 1, userSelect: 'none' } }, '|'),
    h('span', { key: 'lbl-from', style: { fontSize: 12, color: 'var(--t3)', whiteSpace: 'nowrap' } }, 'Din categoria:'),
    h('select', { key: 'dfrom', className: 'btn secondary', style: { padding: '6px 10px' }, value: deptFrom, onChange: function(e){ setDeptFrom(e.target.value); } }, deptOpts),
    h('span', { key: 'lbl-to', style: { fontSize: 12, color: 'var(--t3)', whiteSpace: 'nowrap' } }, 'Spre categoria:'),
    h('select', { key: 'dto', className: 'btn secondary', style: { padding: '6px 10px' }, value: deptTo, onChange: function(e){ setDeptTo(e.target.value); } }, deptOpts),
    h('span', { key: 'sep15', style: { color: 'var(--bd)', fontSize: 18, lineHeight: 1, userSelect: 'none' } }, '|'),
    // Utilizator = assignee-ul din CTS (cine a lucrat mailul), nu sugestia AI.
    h('select', { key: 'asg', className: 'btn secondary', style: { padding: '6px 10px', maxWidth: 200 }, value: assigneeF,
      title: 'Utilizatorul care a preluat mailul în CTS', onChange: function(e){ setAssigneeF(e.target.value); } },
      [h('option', { key: '', value: '' }, 'Toți utilizatorii')].concat(assigneeList.map(function(a){
        return h('option', { key: a.email, value: a.email }, (a.name || a.email) + ' (' + a.count + ')'); }))),
    h('select', { key: 'stf', className: 'btn secondary', style: { padding: '6px 10px' }, value: statusF, onChange: function(e){ setStatusF(e.target.value); } },
      [h('option', { key: '', value: '' }, 'Toate statusurile')].concat(
        ['new', 'in progress', 'solved', 'deleted'].map(function(s){ return h('option', { key: s, value: s }, s); }))),
    h('span', { key: 'sep2', style: { color: 'var(--bd)', fontSize: 18, lineHeight: 1, userSelect: 'none' } }, '|'),
    h('input', { key: 'dtefrom', type: 'date', className: 'btn secondary', style: { padding: '5px 8px', fontFamily: 'inherit', fontSize: 13, cursor: 'pointer', minWidth: 130 }, value: dateFrom, title: 'De la data', onChange: function(e){ setDateFrom(e.target.value); } }),
    h('span', { key: 'lbl-dash', style: { fontSize: 13, color: 'var(--t3)' } }, '—'),
    h('input', { key: 'dteto', type: 'date', className: 'btn secondary', style: { padding: '5px 8px', fontFamily: 'inherit', fontSize: 13, cursor: 'pointer', minWidth: 130 }, value: dateTo, title: 'Pana la data', onChange: function(e){ setDateTo(e.target.value); } }),
    (dateFrom || dateTo || deptFrom || deptTo || searchId || assigneeF || statusF) ? h('button', { key: 'clr', className: 'btn secondary', style: { fontSize: 12, padding: '5px 10px', color: 'var(--rd)' }, onClick: function(){ setDateFrom(''); setDateTo(''); setDeptFrom(''); setDeptTo(''); setSearchId(''); setAssigneeF(''); setStatusF(''); } }, 'Reset filtre') : null,
    h('span', { key: 'cnt', title: 'Numar total de mailuri care corespund filtrelor aplicate', style: { display: 'inline-flex', alignItems: 'center', gap: 5, fontSize: 12, fontWeight: 600, color: 'var(--t2)', border: '1px solid var(--bd)', borderRadius: 999, padding: '4px 11px', fontVariantNumeric: 'tabular-nums' } }, [(data.total != null ? data.total.toLocaleString('ro-RO') : '0'), h('span', { key: 'l', style: { fontWeight: 400, color: 'var(--t3)' } }, 'mailuri')]),
    h('div', { key: 'sp', style: { flex: 1 } }),
    h('span', { key: 'sn', style: { fontSize: 11, color: 'var(--t3)' } }, syncNote),
    h('span', { key: 'au', title: 'Sync rulează automat din cron (~5 min) — butoanele sunt doar pentru declanșare manuală', style: { display: 'inline-flex', alignItems: 'center', gap: 4, fontSize: 11, color: 'var(--gn, #2ea043)', border: '1px solid ' + hexA('#2ea043', 0.3), background: hexA('#2ea043', 0.08), borderRadius: 999, padding: '2px 8px' } }, '⟳ auto · ~5 min'),
    h('button', { key: 'sr', className: 'btn secondary', disabled: syncing, onClick: doSyncRecent, title: 'Re-verifică ultimele 24h — prinde re-încadrările CTS (rulează și automat din cron)' }, syncing ? 'Se sincronizeaza…' : '↻ Sync ultimele 24h'),
    h('button', { key: 'sy', className: 'btn secondary', disabled: syncing, onClick: doSync, title: 'Sync complet — trage tot ground-truth-ul din CTS' }, syncing ? 'Se sincronizeaza…' : 'Sync complet')
  ]);

  var dirTabs = h('div', { key: 'dtabs', style: { display: 'flex', gap: 2, marginBottom: 12, borderBottom: '1px solid var(--bd)' } },
    [['received', '↓ PRIMIT'], ['sent', '↑ TRIMIS']].map(function(t){
      var active = dirTab === t[0];
      var accent = t[0] === 'sent' ? '#1a7f37' : '#185FA5';
      return h('button', { key: t[0], onClick: function(){ setDirTab(t[0]); },
        style: { padding: '9px 22px', fontSize: 13, fontWeight: 700, background: 'transparent', border: 'none',
                 borderBottom: '2px solid ' + (active ? accent : 'transparent'),
                 color: active ? accent : 'var(--t2)', cursor: 'pointer', marginBottom: -1 } }, t[1]);
    }));

  var table = h('div', { key: 'tbl', className: 'card', style: { padding: 0, overflow: 'auto', marginBottom: 0 } }, h('table', { className: 'list-table-full' }, [
    h('thead', { key: 'th' }, h('tr', null, ['ID', 'Recepționat', 'Subiect', 'From', 'Categorie (MG → CTS)', 'Departament (MG → CTS)', 'Asignat (MG → CTS)', 'Direcție'].map(function(c, i){ return h('th', { key: i }, c); }))),
    h('tbody', { key: 'tb' }, (data.items || []).length ? data.items.map(function(it){
      var clickable = !!it.email_id || it.is_sent;
      return h('tr', { key: it.id, className: clickable ? 'clickable' : '', title: it.email_id ? 'Deschide emailul' : (it.is_sent ? 'Vezi emailul trimis (corp + atașamente)' : 'Doar în CTS — nu există în Cargo360'), onClick: it.email_id ? function(){ setSelectedId(it.email_id); } : (it.is_sent ? function(){ setSentDetail(it); } : null) }, [
        h('td', { key: 'id' }, it.email_id ? h(IdCell, { id: it.email_id }) : h('span', { style: { color: 'var(--t3)', fontSize: 11 } }, '—')),
        h('td', { key: 'dt', style: { whiteSpace: 'nowrap' } }, (it.received_at || it.cts_solved_at || it.cts_date) ? dateCell(it.received_at || it.cts_solved_at || it.cts_date) : h('span', { style: { color: 'var(--t3)', fontSize: 11 } }, '—')),
        h('td', { key: 'su', title: it.subject || '', style: { maxWidth: 320, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' } }, it.subject || (it.in_cargo360 ? '(fara subiect)' : h('span', { style: { color: 'var(--t3)' } }, '(doar in CTS)'))),
        h('td', { key: 'fr', style: { fontSize: 12, color: 'var(--t2)', maxWidth: 220, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }, title: (it.is_sent ? ('către ' + (it.cts_to_email || '')) : (it.from_address || it.cts_from_email || '')) },
          it.is_sent ? ('→ ' + (it.cts_to_email || '—')) : (it.from_name || it.from_address || it.cts_from_email || it.message_id || h('span', { style: { color: 'var(--t3)' } }, '—'))),
        h('td', { key: 'c' }, compCell(catBadge(it.ai_category), it.cts_category ? catBadge(it.cts_category) || h('span', { className: 'badge', style: { textTransform: 'none' } }, it.cts_category) : null, it.cat_match, it.cat_unmapped)),
        h('td', { key: 'd' }, [
          compCell(deptBadge(it.ai_department), it.cts_department ? (deptBadge(it.cts_department) || h('span', { className: 'badge', style: { textTransform: 'none' } }, it.cts_department)) : null, it.dep_match, it.dep_unmapped),
          it.changed_at ? h('div', { key: 'chg', title: 'CTS a re-încadrat acest email' + (it.cts_department_prev ? ' (anterior: ' + (DEPT_LABELS[it.cts_department_prev] || it.cts_department_prev) + ')' : '') + ' la ' + new Date(it.changed_at).toLocaleString('ro-RO'), style: { fontSize: 10, color: 'var(--yw)', marginTop: 3, whiteSpace: 'nowrap' } },
            '↻ re-încadrat' + (it.cts_department_prev ? ' (din ' + (DEPT_LABELS[it.cts_department_prev] || it.cts_department_prev) + ')' : '')) : null
        ]),
        h('td', { key: 'asg' }, compCell(assigneeBadge(it.ai_assignee), it.cts_assignee ? assigneeBadge(it.cts_assignee, it.cts_assignee_name) : null, it.asg_match, false)),
        h('td', { key: 't' }, h('div', { style: { display: 'flex', flexDirection: 'column', gap: 3, alignItems: 'flex-start' } }, [
          it.is_sent
            ? h('span', { key: 'dir', title: 'Trimis de noi (reply colegi) — nu se încadrează, exclus din statistici', className: 'badge', style: { textTransform: 'none', background: hexA('#2ea043', 0.12), color: 'var(--gn, #2ea043)', border: '1px solid ' + hexA('#2ea043', 0.35) } }, '↑ TRIMIS')
            : h('span', { key: 'dir', title: 'Mail primit de la client — se compară încadrarea', className: 'badge', style: { textTransform: 'none', background: hexA('#3b82f6', 0.10), color: 'var(--t2)', border: '1px solid ' + hexA('#3b82f6', 0.30) } }, '↓ PRIMIT'),
          it.is_spam ? h('span', { key: 'sp', title: 'CTS a marcat ca SPAM — expeditorul a fost adăugat automat în blacklist', className: 'badge', style: { textTransform: 'none', background: hexA('#ef4444', 0.10), color: 'var(--rd)', border: '1px solid ' + hexA('#ef4444', 0.30) } }, '⛔ SPAM') : null,
          ctsStatusBadge(it.cts_status, 'cs')
        ]))
      ]);
    }) : h('tr', { key: 'empty' }, h('td', { colSpan: 7, style: { textAlign: 'center', padding: 30, color: 'var(--t3)' } },
      'Nicio inregistrare CTS inca. Dupa grant-ul de acces, apasa „Sincronizeaza din CTS".')))
  ]));

  return h('div', { className: 'page' }, [
    h('div', { key: 'intro', style: { fontSize: 13, color: 'var(--t2)', marginBottom: 12 } },
      'Comparatie intre incadrarile Cargo360 (AI) si adevarul de teren din CTS (categorie/departament setate manual de suport + reply-ul trimis). Modul de training — NU influenteaza fluxul curent.'),
    headerCards,
    dirTabs,
    filters,
    loading ? h('div', { key: 'ld', style: { padding: 30, textAlign: 'center', color: 'var(--t3)' } }, 'Se incarca…') : table,
    h('div', { key: 'pg' }, pager(page, totalPages, setPage)),
    (function(){
      // Modal de email IDENTIC cu pagina Emailuri — navigare doar printre rândurile care există în Cargo360.
      var navIds = (data.items || []).filter(function(it){ return it.email_id; }).map(function(it){ return it.email_id; });
      var ci = navIds.indexOf(selectedId);
      return selectedId != null ? h(EmailDetail, {
        key: 'mod', emailId: selectedId, allIds: navIds, currentIndex: ci,
        onNext: function(){ if (ci > -1 && ci < navIds.length - 1) setSelectedId(navIds[ci + 1]); },
        onPrev: function(){ if (ci > 0) setSelectedId(navIds[ci - 1]); },
        onClose: function(){ setSelectedId(null); },
        onChanged: function(){ loadList(); loadStats(); }
      }) : null;
    })(),
    sentDetail ? (function(){
      var sentItems = (data.items || []).filter(function(x){ return x.is_sent; });
      var si = sentItems.findIndex(function(x){ return x.id === sentDetail.id; });
      return h(CtsSentModal, { key: 'sentmod', item: sentDetail, items: sentItems, index: si,
        onClose: function(){ setSentDetail(null); },
        onNext: function(){ if (si > -1 && si < sentItems.length - 1) setSentDetail(sentItems[si + 1]); },
        onPrev: function(){ if (si > 0) setSentDetail(sentItems[si - 1]); } });
    })() : null
  ]);
}

const TONE_COLORS = { neutru: '#6b7280', tensionat: '#ef4444', prietenos: '#22c55e' };
function toneBadge(t) {
  if (!t) return null;
  var col = TONE_COLORS[t] || TONE_COLORS.neutru;
  return h('span', { className: 'badge', style: { background: hexA(col, 0.14), color: col, borderColor: hexA(col, 0.34), textTransform: 'none' } }, t);
}

function CtsCallsTrainingPanel() {
  const [stats, setStats] = useState(null);
  const [data, setData] = useState({ items: [], total: 0, page: 1, page_size: 50 });
  const [loading, setLoading] = useState(true);
  const [page, setPage] = useState(1);
  const [onlyMismatch, setOnlyMismatch] = useState(false);
  const [axis, setAxis] = useState('category');
  const [searchId, setSearchId] = useState('');
  const [dateFrom, setDateFrom] = useState('');
  const [dateTo, setDateTo] = useState('');
  const [deptF, setDeptF] = useState('');       // departamentul assignee-ului CTS
  const [assigneeF, setAssigneeF] = useState('');
  const [statusF, setStatusF] = useState('');
  const [assigneeList, setAssigneeList] = useState([]);
  const [syncing, setSyncing] = useState(false);
  const [cfg, setCfg] = useState(null);
  const [selectedId, setSelectedId] = useState(null);

  // Aceleasi filtre pe lista SI pe carduri — altfel sumarul de sus ar arata tot istoricul.
  function filterQS() {
    var qs = [];
    if (dateFrom) qs.push('date_from=' + encodeURIComponent(dateFrom));
    if (dateTo) qs.push('date_to=' + encodeURIComponent(dateTo));
    if (deptF) qs.push('department=' + encodeURIComponent(deptF));
    if (assigneeF) qs.push('assignee=' + encodeURIComponent(assigneeF));
    if (statusF) qs.push('status=' + encodeURIComponent(statusF));
    return qs;
  }
  function loadStats() {
    var q = filterQS();
    api('/cts-calls-training/stats' + (q.length ? ('?' + q.join('&')) : '')).then(setStats).catch(function(){});
  }
  function loadCfg() { api('/cts-calls-training/sync-config').then(setCfg).catch(function(){}); }
  function loadList() {
    setLoading(true);
    var qs = ['page=' + page, 'page_size=50'].concat(filterQS());
    if (onlyMismatch) { qs.push('only_mismatch=1'); qs.push('axis=' + encodeURIComponent(axis)); }
    if (searchId.trim()) qs.push('search_id=' + encodeURIComponent(searchId.trim()));
    api('/cts-calls-training/list?' + qs.join('&')).then(function(d){ setData(d); setLoading(false); })
      .catch(function(){ setLoading(false); });
  }
  useEffect(function(){ loadCfg(); }, []);
  useEffect(function(){ api('/cts-calls-training/assignees').then(function(d){ setAssigneeList(d.assignees || []); }).catch(function(){}); }, []);
  useEffect(function(){ setPage(1); }, [onlyMismatch, axis, searchId, dateFrom, dateTo, deptF, assigneeF, statusF]);
  useEffect(function(){ loadList(); }, [page, onlyMismatch, axis, searchId, dateFrom, dateTo, deptF, assigneeF, statusF]);
  useEffect(function(){ loadStats(); }, [dateFrom, dateTo, deptF, assigneeF, statusF]);

  // Scurtaturi de interval — cazurile uzuale ("apelurile de azi/ieri") fara sa tastezi doua date.
  function ymd(d) {
    return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
  }
  function setRangeDays(back) {
    var to = new Date(), from = new Date();
    from.setDate(from.getDate() - back);
    setDateFrom(ymd(from)); setDateTo(ymd(to));
  }

  function doSync() {
    setSyncing(true);
    api('/cts-calls-training/sync', { method: 'POST' }).then(function(r){
      setSyncing(false);
      if (r && r.ok) { mgToast('success', 'Sincronizat: ' + r.inserted + ' noi, ' + r.updated + ' actualizate'); loadStats(); loadList(); }
      else { mgToast('info', (r && r.reason) || 'Sync indisponibil'); }
    }).catch(function(){ setSyncing(false); mgToast('error', 'Eroare la sincronizare'); });
  }
  function doSyncRecent() {
    setSyncing(true);
    api('/cts-calls-training/sync-recent?hours=24', { method: 'POST' }).then(function(r){
      if (r && r.started) {
        mgToast('success', (r.message || 'Sync pornit in fundal.') + ' Se actualizeaza...');
        setTimeout(function(){ loadStats(); loadList(); }, 10000);
        setTimeout(function(){ loadStats(); loadList(); setSyncing(false); }, 30000);
        return;
      }
      setSyncing(false);
      if (r && r.ok) { mgToast('success', 'Ultimele 24h: ' + r.inserted + ' noi, ' + r.updated + ' actualizate'); loadStats(); loadList(); }
      else { mgToast('info', (r && r.reason) || 'Sync indisponibil'); }
    }).catch(function(){ setSyncing(false); mgToast('error', 'Eroare la sincronizare'); });
  }

  function rate(v) { return v == null ? '—' : (v + '%'); }
  function rateColor(v) { return v == null ? 'var(--t3)' : (v >= 85 ? 'var(--gn)' : v >= 70 ? 'var(--yw)' : 'var(--rd)'); }

  function statCard(title, val, sub, color) {
    return h('div', { className: 'card', style: { flex: '1 1 150px', minWidth: 140, padding: '12px 15px', borderTop: '3px solid ' + (color || '#30363d') } }, [
      h('div', { key: 't', style: { fontSize: 10, color: 'var(--t3)', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '.06em' } }, title),
      h('div', { key: 'v', style: { fontSize: 24, fontWeight: 800, lineHeight: 1.15, marginTop: 5 } }, val),
      sub ? h('div', { key: 's', style: { fontSize: 11, color: 'var(--t3)', marginTop: 3 } }, sub) : null
    ]);
  }

  function compCell(aiNode, ctsNode, match) {
    var bg = match === false ? hexA('#ef4444', 0.10) : 'transparent';
    var bd = match === false ? '1px solid ' + hexA('#ef4444', 0.40) : '1px solid transparent';
    return h('div', { style: { display: 'flex', alignItems: 'center', gap: 6, flexWrap: 'wrap', padding: '3px 6px', borderRadius: 6, background: bg, border: bd } }, [
      aiNode || h('span', { key: 'a', style: { color: 'var(--t3)', fontSize: 11 } }, '—'),
      h('span', { key: 'ar', style: { color: 'var(--t3)', fontSize: 12 } }, '→'),
      ctsNode || h('span', { key: 'c', style: { color: 'var(--t3)', fontSize: 11 } }, '—'),
      match === true ? h('span', { key: 'ok', style: { color: 'var(--gn)', fontWeight: 700, fontSize: 13 } }, '✓')
        : (match === false ? h('span', { key: 'x', style: { color: 'var(--rd)', fontWeight: 700, fontSize: 13 } }, '✗') : null)
    ]);
  }

  function durationLabel(sec) {
    if (sec == null) return '—';
    var m = Math.floor(sec / 60), s = sec % 60;
    return m + ':' + (s < 10 ? '0' : '') + s;
  }

  var st = stats || {};
  var catS = st.category || {}; var asgS = st.assignee || {};
  var totalPages = Math.max(1, Math.ceil((data.total || 0) / (data.page_size || 50)));

  var headerCards = h('div', { key: 'cards', style: { display: 'flex', gap: 12, flexWrap: 'wrap', marginBottom: 14 } }, [
    statCard('Potrivire categorie', rate(catS.match_rate), (catS.matched || 0) + ' / ' + (catS.comparable || 0) + ' comparabile', rateColor(catS.match_rate)),
    statCard('Potrivire asignare', rate(asgS.match_rate), (asgS.matched || 0) + ' / ' + (asgS.comparable || 0) + ' comparabile', rateColor(asgS.match_rate)),
    statCard('Timp mediu de răspuns', st.avg_response_seconds != null ? durationLabel(Math.round(st.avg_response_seconds)) : '—', 'raportat de CTS', 'var(--tx)'),
    statCard('Total apeluri CTS', (st.total || 0), (st.only_in_cts || 0) + ' doar în CTS', 'var(--tx)'),
    statCard('Neîncadrate în CTS', (st.pending_unclassified || 0), 'în așteptarea operatorului', 'var(--t2)')
  ]);

  var syncNote = cfg ? (cfg.active ? 'Sync activ'
    : (cfg.gateway_configured ? 'Gateway configurat, sync dezactivat' : 'Endpoint /cts/calls neconfigurat — în așteptarea Razvan')) : '';

  var filters = h('div', { key: 'flt', style: { display: 'flex', gap: 10, alignItems: 'center', flexWrap: 'wrap', marginBottom: 10 } }, [
    h('label', { key: 'm', style: { display: 'flex', alignItems: 'center', gap: 6, fontSize: 13, cursor: 'pointer' } }, [
      h('input', { key: 'i', type: 'checkbox', checked: onlyMismatch, onChange: function(e){ setOnlyMismatch(e.target.checked); } }),
      'Doar divergente'
    ]),
    onlyMismatch ? h('select', { key: 'ax', className: 'btn secondary', style: { padding: '6px 10px' }, value: axis, onChange: function(e){ setAxis(e.target.value); } },
      [h('option', { key: 'category', value: 'category' }, 'Categorie'), h('option', { key: 'assignee', value: 'assignee' }, 'Asignare')]) : null,
    h('span', { key: 'sep0', style: { color: 'var(--bd)', fontSize: 18, lineHeight: 1, userSelect: 'none' } }, '|'),
    h('span', { key: 'dl', style: { fontSize: 12, color: 'var(--t3)' } }, 'De la'),
    h('input', { key: 'df', type: 'date', value: dateFrom, max: dateTo || undefined,
      className: 'btn secondary', style: { padding: '5px 8px', fontFamily: 'inherit', fontSize: 13 },
      onChange: function(e){ setDateFrom(e.target.value); } }),
    h('span', { key: 'dl2', style: { fontSize: 12, color: 'var(--t3)' } }, 'până la'),
    h('input', { key: 'dt', type: 'date', value: dateTo, min: dateFrom || undefined,
      className: 'btn secondary', style: { padding: '5px 8px', fontFamily: 'inherit', fontSize: 13 },
      onChange: function(e){ setDateTo(e.target.value); } }),
    h('button', { key: 'd0', className: 'btn secondary', style: { fontSize: 12, padding: '5px 9px' },
      title: 'Apelurile de azi', onClick: function(){ setRangeDays(0); } }, 'Azi'),
    h('button', { key: 'd7', className: 'btn secondary', style: { fontSize: 12, padding: '5px 9px' },
      title: 'Ultimele 7 zile', onClick: function(){ setRangeDays(7); } }, '7 zile'),
    (dateFrom || dateTo) ? h('button', { key: 'dclr', className: 'btn secondary',
      style: { fontSize: 12, padding: '5px 9px', color: 'var(--rd)' },
      onClick: function(){ setDateFrom(''); setDateTo(''); } }, 'Șterge datele') : null,
    h('span', { key: 'sepf', style: { color: 'var(--bd)', fontSize: 18, lineHeight: 1, userSelect: 'none' } }, '|'),
    // Departament = al assignee-ului CTS (apelul nu are departament propriu în CTS).
    h('select', { key: 'dep', className: 'btn secondary', style: { padding: '6px 10px' }, value: deptF,
      title: 'Departamentul utilizatorului care a preluat apelul în CTS', onChange: function(e){ setDeptF(e.target.value); } },
      [h('option', { key: '', value: '' }, 'Toate departamentele')].concat(DEPT_SLUGS.map(function(s){
        return h('option', { key: s, value: s }, DEPT_LABELS[s]); }))),
    h('select', { key: 'asg', className: 'btn secondary', style: { padding: '6px 10px', maxWidth: 200 }, value: assigneeF,
      onChange: function(e){ setAssigneeF(e.target.value); } },
      [h('option', { key: '', value: '' }, 'Toți utilizatorii')].concat(assigneeList.map(function(a){
        return h('option', { key: a.email, value: a.email }, (a.name || a.email) + ' (' + a.count + ')'); }))),
    h('select', { key: 'stf', className: 'btn secondary', style: { padding: '6px 10px' }, value: statusF,
      onChange: function(e){ setStatusF(e.target.value); } },
      [h('option', { key: '', value: '' }, 'Toate statusurile')].concat(
        ['new', 'in progress', 'solved'].map(function(s){ return h('option', { key: s, value: s }, s); }))),
    h('span', { key: 'sep1', style: { color: 'var(--bd)', fontSize: 18, lineHeight: 1, userSelect: 'none' } }, '|'),
    h('input', { key: 'sid', type: 'text', inputMode: 'numeric', placeholder: 'Caută ID apel…', value: searchId,
      className: 'btn secondary', style: { padding: '6px 10px', width: 140, fontFamily: 'inherit', fontSize: 13 },
      onChange: function(e){ setSearchId(e.target.value.replace(/[^0-9]/g, '')); } }),
    searchId ? h('button', { key: 'clr', className: 'btn secondary', style: { fontSize: 12, padding: '5px 10px', color: 'var(--rd)' }, onClick: function(){ setSearchId(''); } }, 'Reset') : null,
    h('div', { key: 'sp', style: { flex: 1 } }),
    h('span', { key: 'sn', style: { fontSize: 11, color: 'var(--t3)' } }, syncNote),
    h('span', { key: 'au', title: 'Sync rulează automat din cron (~5 min) — butoanele sunt doar pentru declanșare manuală', style: { display: 'inline-flex', alignItems: 'center', gap: 4, fontSize: 11, color: 'var(--gn, #2ea043)', border: '1px solid ' + hexA('#2ea043', 0.3), background: hexA('#2ea043', 0.08), borderRadius: 999, padding: '2px 8px' } }, '⟳ auto · ~5 min'),
    h('button', { key: 'sr', className: 'btn secondary', disabled: syncing, onClick: doSyncRecent, title: 'Re-verifică ultimele 24h' }, syncing ? 'Se sincronizeaza…' : '↻ Sync ultimele 24h'),
    h('button', { key: 'sy', className: 'btn secondary', disabled: syncing, onClick: doSync, title: 'Sync complet' }, syncing ? 'Se sincronizeaza…' : 'Sync complet')
  ]);

  var table = h('div', { key: 'tbl', className: 'card', style: { padding: 0, overflow: 'auto', marginBottom: 0 } }, h('table', { className: 'list-table-full' }, [
    h('thead', { key: 'th' }, h('tr', null, ['ID', 'Data apel', 'Telefon', 'Client', 'Categorie (MG → CTS)', 'Stil', 'Asignat (MG → CTS)', 'Timp răspuns', 'Status'].map(function(c, i){ return h('th', { key: i }, c); }))),
    h('tbody', { key: 'tb' }, (data.items || []).length ? data.items.map(function(it){
      var clickable = !!it.call_id;
      return h('tr', { key: it.id, className: clickable ? 'clickable' : '', title: clickable ? 'Deschide apelul' : 'Doar în CTS — apelul nu a fost încă ingerat din While1', onClick: clickable ? function(){ setSelectedId(it.call_id); } : null }, [
        h('td', { key: 'id' }, it.call_id ? h(IdCell, { id: it.call_id }) : h('span', { style: { color: 'var(--t3)', fontSize: 11 } }, '—')),
        h('td', { key: 'dt', style: { whiteSpace: 'nowrap' } }, it.started_at ? dateCell(it.started_at) : h('span', { style: { color: 'var(--t3)', fontSize: 11 } }, '—')),
        h('td', { key: 'ph', style: { fontSize: 12 } }, it.caller_number || '—'),
        h('td', { key: 'cl', style: { fontSize: 12, maxWidth: 200, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' } }, it.client_name || h('span', { style: { color: 'var(--t3)' } }, '—')),
        h('td', { key: 'c' }, compCell(catBadge(it.ai_category), it.cts_category ? (catBadge(it.cts_category) || h('span', { className: 'badge', style: { textTransform: 'none' } }, it.cts_category)) : null, it.cat_match)),
        h('td', { key: 'tn' }, toneBadge(it.ai_tone) || h('span', { style: { color: 'var(--t3)', fontSize: 11 } }, '—')),
        h('td', { key: 'asg' }, compCell(assigneeBadge(it.ai_assignee), it.cts_assignee ? assigneeBadge(it.cts_assignee, it.cts_assignee_name) : null, it.asg_match)),
        h('td', { key: 'rt', style: { fontSize: 12, color: 'var(--t2)', whiteSpace: 'nowrap' }, title: 'Timp până la răspuns (ring_seconds, raportat de CTS)' }, it.cts_response_seconds != null ? durationLabel(it.cts_response_seconds) : h('span', { style: { color: 'var(--t3)' } }, '—')),
        h('td', { key: 'st' }, ctsStatusBadge(it.cts_status) || h('span', { style: { color: 'var(--t3)', fontSize: 11 } }, '—'))
      ]);
    }) : h('tr', { key: 'empty' }, h('td', { colSpan: 9, style: { textAlign: 'center', padding: 30, color: 'var(--t3)' } },
      'Nicio înregistrare CTS încă. După grant-ul de acces, apasă „Sincronizează din CTS".')))
  ]));

  // Banner prospetime: distinge "Cargo360 nu a sincronizat" de "CTS nu a mai scris nimic".
  // Fara el, un blocaj in amonte arata identic cu un bug de sincronizare (vezi 2026-07-31).
  var freshBanner = (function(){
    var f = st.freshness;
    if (!f || f.lag_minutes == null) return null;
    var lag = f.lag_minutes;
    if (lag < 45) return null;                       // decalaj normal: fisa se scrie la finalul apelului
    var sev = lag >= 90;
    var col = sev ? 'var(--rd)' : 'var(--yw)';
    function hhmm(s) { return s ? String(s).slice(11, 16) : '—'; }
    return h('div', { key: 'fresh', style: {
      display: 'flex', alignItems: 'flex-start', gap: 10, padding: '10px 13px', marginBottom: 12,
      borderRadius: 8, border: '1px solid ' + col,
      background: 'color-mix(in srgb, ' + col + ' 10%, transparent)' } }, [
      h('svg', { key: 'ic', width: 18, height: 18, viewBox: '0 0 24 24', fill: 'none',
        stroke: 'currentColor', strokeWidth: 2, strokeLinecap: 'round', strokeLinejoin: 'round',
        style: { color: col, flexShrink: 0, marginTop: 1 } }, [
        h('circle', { key: 'c', cx: 12, cy: 12, r: 10 }),
        h('path', { key: 'l', d: 'M12 8v4' }),
        h('path', { key: 'd', d: 'M12 16h.01' })
      ]),
      h('div', { key: 'tx', style: { fontSize: 12.5, lineHeight: 1.5 } }, [
        h('strong', { key: 'h', style: { color: col } },
          'CTS a rămas în urmă cu ' + (lag >= 120 ? Math.round(lag / 60) + ' ore' : lag + ' minute') + '.'),
        h('div', { key: 'b', style: { color: 'var(--t2)', marginTop: 3 } },
          'Cel mai nou apel primit din CTS: ' + hhmm(f.last_cts_call_at) +
          ' · ultimul apel în centrală: ' + hhmm(f.last_while1_call_at) +
          (f.while1_last_2h ? ' · ' + f.while1_last_2h_without_cts + ' din ' + f.while1_last_2h +
            ' apeluri din ultimele 2h nu au ajuns încă în CTS' : '')),
        h('div', { key: 'c2', style: { color: 'var(--t3)', marginTop: 3 } },
          'Cargo360 interoghează CTS la fiecare 5 minute și preia tot ce primește. ' +
          'Apelurile care lipsesc nu sunt returnate de CTS la momentul interogării — ' +
          'cauza se află în amonte, nu în Cargo360.')
      ])
    ]);
  })();

  return h('div', { className: 'page' }, [
    h('div', { key: 'intro', style: { fontSize: 13, color: 'var(--t2)', marginBottom: 12 } },
      'Comparație între încadrarea Cargo360 (AI, pe baza transcriptului) și adevărul de teren din CTS (categorie/asignare/status setate de operator). Modul de training — NU influențează fluxul curent.'),
    freshBanner,
    headerCards,
    filters,
    loading ? h('div', { key: 'ld', style: { padding: 30, textAlign: 'center', color: 'var(--t3)' } }, 'Se incarca…') : table,
    h('div', { key: 'pg' }, pager(page, totalPages, setPage)),
    (function(){
      var navIds = (data.items || []).filter(function(it){ return it.call_id; }).map(function(it){ return it.call_id; });
      var ci = navIds.indexOf(selectedId);
      return selectedId != null ? h(CallDetail, {
        key: 'mod', callId: selectedId, allIds: navIds, currentIndex: ci,
        onNext: function(){ if (ci > -1 && ci < navIds.length - 1) setSelectedId(navIds[ci + 1]); },
        onPrev: function(){ if (ci > 0) setSelectedId(navIds[ci - 1]); },
        onClose: function(){ setSelectedId(null); }
      }) : null;
    })()
  ]);
}

// Always-visible AI category bar with confidence + re-run button. Used in both modals.
function AiCategoryBar({ email, onUpdated }) {
  const [busy, setBusy] = useState(false);
  if (!email) return null;
  const cat = email.ai_category;
  const conf = (email.ai_result && email.ai_result.confidence != null) ? email.ai_result.confidence : null;
  function rerun() {
    setBusy(true);
    api('/ai/category/' + email.id + '/run', { method: 'POST' }).then(function(r) {
      setBusy(false);
      if (r && r.ai_result) { if (onUpdated) onUpdated({ ai_category: r.ai_category, ai_result: r.ai_result, ai_status: 'done' }); mgToast('success', 'Reclasificat: ' + r.ai_category); }
      else { Swal.fire({ icon: 'error', title: 'Eroare', text: (r && r.detail) || 'Reclasificare eșuată', background: 'var(--bg2,#0e131c)', color: 'var(--tx,#e6edf3)' }); }
    }).catch(function(e) { setBusy(false); Swal.fire({ icon: 'error', title: 'Eroare', text: String((e && e.message) || e), background: 'var(--bg2,#0e131c)', color: 'var(--tx,#e6edf3)' }); });
  }
  function correct(nc) {
    if (!nc || nc === cat) return;
    setBusy(true);
    api('/ai/category/' + email.id + '/correct', { method: 'POST', body: JSON.stringify({ category: nc }) }).then(function(r) {
      setBusy(false);
      if (r && r.ai_result) { if (onUpdated) onUpdated({ ai_category: r.new_category, ai_result: r.ai_result, ai_status: 'done' }); mgToast('success', 'Categorie corectată: ' + r.new_category); }
      else { Swal.fire({ icon: 'error', title: 'Eroare', text: (r && r.detail) || 'Corectare eșuată', background: 'var(--bg2,#0e131c)', color: 'var(--tx,#e6edf3)' }); }
    }).catch(function(e) { setBusy(false); Swal.fire({ icon: 'error', title: 'Eroare', text: String((e && e.message) || e), background: 'var(--bg2,#0e131c)', color: 'var(--tx,#e6edf3)' }); });
  }
  return h('div', { style: { display: 'flex', alignItems: 'center', gap: 10, padding: '8px 16px', borderBottom: '1px solid var(--bd,#222)', background: 'var(--bg2)', fontSize: 12, flexWrap: 'wrap' } }, [
    h('span', { key: 'l', style: { color: 'var(--t2)', fontWeight: 600 } }, 'AI categorie:'),
    cat ? h('span', { key: 'c', className: 'badge', style: { background: CAT_COLORS[cat] || CAT_COLORS.necunoscut, color: '#fff', textTransform: 'none', fontSize: 12 } }, cat)
        : h('span', { key: 'c', style: { color: 'var(--t3)' } }, 'neclasificat'),
    (conf != null) ? h('span', { key: 'cf', style: { color: 'var(--t2)' } }, ['confidență: ', h('b', { key: 'b', style: { color: conf >= 0.75 ? 'var(--gn)' : conf >= 0.5 ? 'var(--yw)' : 'var(--rd)' } }, Math.round(conf * 100) + '%')]) : null,
    h('span', { key: 'st', style: { fontSize: 11, color: email.ai_status === 'done' ? 'var(--gn)' : email.ai_status === 'error' ? 'var(--rd)' : 'var(--yw)' } }, '(' + (email.ai_status === 'done' ? 'procesat' : email.ai_status === 'error' ? 'eroare' : 'neprocesat') + ')'),
    (email.ai_result && email.ai_result.reason) ? h('span', { key: 'r', style: { color: 'var(--t3)', flexBasis: '100%', fontSize: 11 } }, '▸ ' + email.ai_result.reason) : null,
    h('span', { key: 'corrl', style: { marginLeft: 'auto', color: 'var(--t2)' } }, 'Corectează:'),
    h('select', { key: 'corr', value: cat || 'necunoscut', disabled: busy, onChange: function(e) { correct(e.target.value); }, className: 'btn secondary', style: { padding: '3px 8px', fontSize: 11 } },
      ['informatie', 'sesizare', 'reclamatie', 'necunoscut'].map(function(c) { return h('option', { key: c, value: c }, c); })),
    h('button', { key: 'rr', className: 'btn secondary', style: { padding: '3px 10px', fontSize: 11 }, disabled: busy, onClick: rerun }, busy ? 'Se reruleaza...' : 'Reclasifică AI')
  ]);
}

