// Emails page with 4 sub-tabs: Toate / Email / Carantinate / Spam.
// Each child owns the topbar (sets it on mount), so switching tabs swaps it cleanly.
function EmailsPage({ setTopbarRight }) {
  const [sub, setSub] = useState('toate');
  const SUBS = [
    { k: 'toate', l: 'Toate' },
    { k: 'email', l: 'Email' },
    { k: 'carantinate', l: 'Carantinate' },
    { k: 'spam', l: 'Spam' },
  ];
  const body =
    sub === 'spam' ? h(Spam, { key: 'spam', setTopbarRight }) :
    sub === 'carantinate' ? h(EmailsList, { key: 'carantinate', setTopbarRight, lockStatus: 'quarantined,quarantined_strict' }) :
    sub === 'email' ? h(EmailsList, { key: 'email', setTopbarRight, lockStatus: 'clean' }) :
    h(EmailsList, { key: 'toate', setTopbarRight });
  return h('div', { style: { height: '100%', display: 'flex', flexDirection: 'column', minHeight: 0 } }, [
    h('div', { key: 'tabs', className: 'modal-tabs', style: { borderBottom: '1px solid var(--bd)', marginBottom: 8, flexShrink: 0 } },
      SUBS.map(function(s) { return h('button', { key: s.k, className: 'tab' + (sub === s.k ? ' active' : ''), onClick: function() { setSub(s.k); } }, s.l); })),
    h('div', { key: 'body', style: { flex: 1, minHeight: 0, display: 'flex', flexDirection: 'column' } }, body)
  ]);
}

